{
  "status": "SUPPORTED",
  "task_summary": "Find fasteners and tools in storage, use them to fasten a target on the workbench, then put the tool back on the bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The object or location on the workbench that requires securing.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["assembly", "fixture", "workpiece"],
        "required_properties": ["has_connection_points"]
      },
      {
        "id": "fastener_component",
        "entity_kind": "OBJECT",
        "function": "The physical part (screw, bolt, etc.) needed to secure the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "pin"],
        "required_properties": ["fits_fastening_target"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "drill", "implement"],
        "required_properties": ["can_drive_fastener"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The table top where the target sits and tools are placed.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tabletop", "surface"],
        "required_properties": ["is_horizontal", "is_workbench"]
      },
      {
        "id": "storage_region",
        "entity_kind": "REGION",
        "function": "Closed containers where components and tools might be hidden.",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet", "compartment"],
        "required_properties": ["is_closed", "is_storage"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "fits",
        "participant_roles": ["fastener_component", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "operates_on",
        "participant_roles": ["tool", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "relation_3",
        "relation": "rests_on",
        "participant_roles": ["tool", "workbench_surface"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "search_for_items",
        "participant_roles": ["storage_region", "fastener_component", "tool"],
        "operation_count": 1
      },
      {
        "id": "operation_2",
        "operation": "apply_fastener",
        "participant_roles": ["fastening_target", "fastener_component", "tool"],
        "operation_count": 1
      },
      {
        "id": "operation_3",
        "operation": "place_tool",
        "participant_roles": ["tool", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {"label": "yellow_assembly_on_table", "visual_description": "A yellow blocky object sitting on a black base on the wooden table."}
      ],
      "fastener_component": [],
      "tool": [],
      "workbench_surface": [
        {"label": "wooden_table_top", "visual_description": "The light brown wooden surface of the desk."}
      ],
      "storage_region": [
        {"label": "blue_cabinet", "visual_description": "A tall blue cabinet standing against the back wall."},
        {"label": "left_drawer", "visual_description": "The left blue drawer beneath the table."},
        {"label": "right_drawer", "visual_description": "The right blue drawer beneath the table."}
      ]
    },
    "inspectable_regions": [
      {"id": "blue_cabinet", "label": "blue_cabinet", "visual_description": "Tall blue cabinet with a handle, appears closed.", "reason": "Likely contains tools or spare parts."},
      {"id": "left_drawer", "label": "left_drawer", "visual_description": "Drawer with white handle, appears closed.", "reason": "Likely contains small tools or components."},
      {"id": "right_drawer", "label": "right_drawer", "visual_description": "Drawer with white handle, appears closed.", "reason": "Likely contains small tools or components."}
    ],
    "inspection_order": ["blue_cabinet", "left_drawer", "right_drawer"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
